    /// <summary>
    /// Resolves the endpoint for a full set of endpoint parameters.
    /// </summary>
    public static SmithyEndpoint Resolve(AmazonS3EndpointParameters parameters)
    {
        ArgumentNullException.ThrowIfNull(parameters);
        var bucket = parameters.Bucket;
        var region = parameters.Region;
        var useFIPS = parameters.UseFIPS;
        var useDualStack = parameters.UseDualStack;
        var endpoint = parameters.Endpoint;
        var forcePathStyle = parameters.ForcePathStyle;
        var accelerate = parameters.Accelerate;
        var useGlobalEndpoint = parameters.UseGlobalEndpoint;
        var useObjectLambdaEndpoint = parameters.UseObjectLambdaEndpoint;
        var key = parameters.Key;
        var prefix = parameters.Prefix;
        var copySource = parameters.CopySource;
        var disableAccessPoints = parameters.DisableAccessPoints;
        var disableMultiRegionAccessPoints = parameters.DisableMultiRegionAccessPoints;
        var useArnRegion = parameters.UseArnRegion;
        var useS3ExpressControlEndpoint = parameters.UseS3ExpressControlEndpoint;
        var disableS3ExpressSessionAuth = parameters.DisableS3ExpressSessionAuth;
        AwsPartition? partitionResult = null;
        string? accessPointSuffix = null;
        string? regionPrefix = null;
        string? outpostIdSsa2 = null;
        string? hardwareType = null;
        string? s3eDs = null;
        string? s3eFips = null;
        string? s3eAuth = null;
        EndpointUrl? url = null;
        AwsArn? bucketArn = null;
        string? s3expressAvailabilityZoneId = null;
        string? uriEncodedBucket = null;
        string? arnType = null;
        string? accessPointNameSsa1 = null;
        AwsPartition? bucketPartition = null;
        string? outpostIdSsa1 = null;
        string? outpostType = null;
        string? accessPointNameSsa2 = null;

        var nodes = Nodes;
        var reference = Root;
        while (IsNode(reference))
        {
            var index = (reference > 0 ? reference : -reference) - 1;
            var outcome = Test(nodes[index * 3]) ^ (reference < 0);
            reference = outcome ? nodes[index * 3 + 1] : nodes[index * 3 + 2];
        }
        return reference >= ResultOffset
            ? Result(reference - ResultOffset)
            : throw SmithyEndpointResolutionException.NoMatch();

        bool Test(int condition) =>
            condition switch
            {
                // isSet(Region)
                0 => region is not null,
                // booleanEquals(Accelerate, true)
                1 => accelerate == true,
                // booleanEquals(UseFIPS, true)
                2 => useFIPS == true,
                // booleanEquals(UseDualStack, true)
                3 => useDualStack == true,
                // isSet(Endpoint)
                4 => endpoint is not null,
                // isSet(Bucket)
                5 => bucket is not null,
                // stringEquals(coalesce(substring(Bucket, 0, 6, true), ""), "--x-s3")
                6 => ((EndpointFunctions.Substring(bucket!, 0, 6, true)) ?? ("")) == ("--x-s3"),
                // stringEquals(coalesce(substring(Bucket, 0, 7, true), ""), "--xa-s3")
                7 => ((EndpointFunctions.Substring(bucket!, 0, 7, true)) ?? ("")) == ("--xa-s3"),
                // partitionResult = aws.partition(Region)
                8 => (partitionResult = AwsEndpointFunctions.Partition(region!)) is not null,
                // accessPointSuffix = substring(Bucket, 0, 7, true)
                9 => (accessPointSuffix = EndpointFunctions.Substring(bucket!, 0, 7, true))
                    is not null,
                // stringEquals(accessPointSuffix, "--op-s3")
                10 => accessPointSuffix! == ("--op-s3"),
                // regionPrefix = substring(Bucket, 8, 12, true)
                11 => (regionPrefix = EndpointFunctions.Substring(bucket!, 8, 12, true))
                    is not null,
                // outpostId_ssa_2 = substring(Bucket, 32, 49, true)
                12 => (outpostIdSsa2 = EndpointFunctions.Substring(bucket!, 32, 49, true))
                    is not null,
                // hardwareType = substring(Bucket, 49, 50, true)
                13 => (hardwareType = EndpointFunctions.Substring(bucket!, 49, 50, true))
                    is not null,
                // booleanEquals(ForcePathStyle, true)
                14 => forcePathStyle == true,
                // stringEquals(partitionResult#name, "aws-cn")
                15 => partitionResult!.Name == ("aws-cn"),
                // _s3e_ds = ite(UseDualStack, ".dualstack", "")
                16 => (s3eDs = useDualStack ? (".dualstack") : ("")) is not null,
                // isValidHostLabel(outpostId_ssa_2, false)
                17 => EndpointFunctions.IsValidHostLabel(outpostIdSsa2!, false),
                // _s3e_fips = ite(UseFIPS, "-fips", "")
                18 => (s3eFips = useFIPS ? ("-fips") : ("")) is not null,
                // _s3e_auth = ite(coalesce(DisableS3ExpressSessionAuth, false), "sigv4", "sigv4-s3express")
                19 => (
                    s3eAuth =
                        (disableS3ExpressSessionAuth ?? false) ? ("sigv4") : ("sigv4-s3express")
                )
                    is not null,
                // aws.isVirtualHostableS3Bucket(Bucket, false)
                20 => AwsEndpointFunctions.IsVirtualHostableS3Bucket(bucket!, false),
                // url = parseURL(Endpoint)
                21 => (url = EndpointFunctions.ParseUrl(endpoint!)) is not null,
                // booleanEquals(coalesce(UseS3ExpressControlEndpoint, false), true)
                22 => (useS3ExpressControlEndpoint ?? false) == true,
                // aws.isVirtualHostableS3Bucket(Bucket, true)
                23 => AwsEndpointFunctions.IsVirtualHostableS3Bucket(bucket!, true),
                // stringEquals(url#scheme, "http")
                24 => url!.Scheme == ("http"),
                // isValidHostLabel(Region, false)
                25 => EndpointFunctions.IsValidHostLabel(region!, false),
                // bucketArn = aws.parseArn(Bucket)
                26 => (bucketArn = AwsEndpointFunctions.ParseArn(bucket!)) is not null,
                // s3expressAvailabilityZoneId = split(Bucket, "--", 0)#[-2]
                27 => (
                    s3expressAvailabilityZoneId = EndpointFunctions.Index(
                        EndpointFunctions.Split(bucket!, "--", 0),
                        -2
                    )
                )
                    is not null,
                // stringEquals(coalesce(substring(Bucket, 0, 4, false), ""), "arn:")
                28 => ((EndpointFunctions.Substring(bucket!, 0, 4, false)) ?? ("")) == ("arn:"),
                // stringEquals(coalesce(substring(Bucket, 16, 18, true), ""), "--")
                29 => ((EndpointFunctions.Substring(bucket!, 16, 18, true)) ?? ("")) == ("--"),
                // booleanEquals(url#isIp, true)
                30 => url!.IsIp == true,
                // stringEquals(coalesce(substring(Bucket, 21, 23, true), ""), "--")
                31 => ((EndpointFunctions.Substring(bucket!, 21, 23, true)) ?? ("")) == ("--"),
                // stringEquals(coalesce(substring(Bucket, 27, 29, true), ""), "--")
                32 => ((EndpointFunctions.Substring(bucket!, 27, 29, true)) ?? ("")) == ("--"),
                // stringEquals(regionPrefix, "beta")
                33 => regionPrefix! == ("beta"),
                // uri_encoded_bucket = uriEncode(Bucket)
                34 => (uriEncodedBucket = EndpointFunctions.UriEncode(bucket!)) is not null,
                // isValidHostLabel(Region, true)
                35 => EndpointFunctions.IsValidHostLabel(region!, true),
                // booleanEquals(coalesce(UseObjectLambdaEndpoint, false), true)
                36 => (useObjectLambdaEndpoint ?? false) == true,
                // arnType = bucketArn#resourceId[0]
                37 => (arnType = EndpointFunctions.Index(bucketArn!.ResourceId, 0)) is not null,
                // stringEquals(arnType, "")
                38 => arnType! == (""),
                // stringEquals(arnType, "accesspoint")
                39 => arnType! == ("accesspoint"),
                // accessPointName_ssa_1 = bucketArn#resourceId[1]
                40 => (accessPointNameSsa1 = EndpointFunctions.Index(bucketArn!.ResourceId, 1))
                    is not null,
                // stringEquals(accessPointName_ssa_1, "")
                41 => accessPointNameSsa1! == (""),
                // stringEquals(bucketArn#region, "")
                42 => bucketArn!.Region == (""),
                // stringEquals(coalesce(substring(Bucket, 14, 16, true), ""), "--")
                43 => ((EndpointFunctions.Substring(bucket!, 14, 16, true)) ?? ("")) == ("--"),
                // stringEquals(hardwareType, "e")
                44 => hardwareType! == ("e"),
                // stringEquals(hardwareType, "o")
                45 => hardwareType! == ("o"),
                // stringEquals(Region, "aws-global")
                46 => region! == ("aws-global"),
                // stringEquals(coalesce(substring(Bucket, 19, 21, true), ""), "--")
                47 => ((EndpointFunctions.Substring(bucket!, 19, 21, true)) ?? ("")) == ("--"),
                // stringEquals(bucketArn#service, "s3-object-lambda")
                48 => bucketArn!.Service == ("s3-object-lambda"),
                // booleanEquals(coalesce(DisableAccessPoints, false), true)
                49 => (disableAccessPoints ?? false) == true,
                // stringEquals(bucketArn#service, "s3-outposts")
                50 => bucketArn!.Service == ("s3-outposts"),
                // bucketPartition = aws.partition(bucketArn#region)
                51 => (bucketPartition = AwsEndpointFunctions.Partition(bucketArn!.Region))
                    is not null,
                // isValidHostLabel(accessPointName_ssa_1, true)
                52 => EndpointFunctions.IsValidHostLabel(accessPointNameSsa1!, true),
                // stringEquals(coalesce(substring(Bucket, 26, 28, true), ""), "--")
                53 => ((EndpointFunctions.Substring(bucket!, 26, 28, true)) ?? ("")) == ("--"),
                // stringEquals(coalesce(substring(Bucket, 15, 17, true), ""), "--")
                54 => ((EndpointFunctions.Substring(bucket!, 15, 17, true)) ?? ("")) == ("--"),
                // bucketArn#resourceId[4]
                55 => (EndpointFunctions.Index(bucketArn!.ResourceId, 4)) is not null,
                // stringEquals(coalesce(substring(Bucket, 20, 22, true), ""), "--")
                56 => ((EndpointFunctions.Substring(bucket!, 20, 22, true)) ?? ("")) == ("--"),
                // booleanEquals(UseGlobalEndpoint, true)
                57 => useGlobalEndpoint == true,
                // stringEquals(Region, "us-east-1")
                58 => region! == ("us-east-1"),
                // outpostId_ssa_1 = bucketArn#resourceId[1]
                59 => (outpostIdSsa1 = EndpointFunctions.Index(bucketArn!.ResourceId, 1))
                    is not null,
                // booleanEquals(coalesce(UseArnRegion, true), true)
                60 => (useArnRegion ?? true) == true,
                // isValidHostLabel(outpostId_ssa_1, false)
                61 => EndpointFunctions.IsValidHostLabel(outpostIdSsa1!, false),
                // outpostType = bucketArn#resourceId[2]
                62 => (outpostType = EndpointFunctions.Index(bucketArn!.ResourceId, 2)) is not null,
                // stringEquals(Region, bucketArn#region)
                63 => region! == bucketArn!.Region,
                // stringEquals(bucketPartition#name, partitionResult#name)
                64 => bucketPartition!.Name == partitionResult!.Name,
                // booleanEquals(DisableMultiRegionAccessPoints, true)
                65 => disableMultiRegionAccessPoints == true,
                // isValidHostLabel(bucketArn#region, true)
                66 => EndpointFunctions.IsValidHostLabel(bucketArn!.Region, true),
                // stringEquals(bucketArn#partition, partitionResult#name)
                67 => bucketArn!.Partition == partitionResult!.Name,
                // stringEquals(bucketArn#accountId, "")
                68 => bucketArn!.AccountId == (""),
                // stringEquals(bucketArn#service, "s3")
                69 => bucketArn!.Service == ("s3"),
                // isValidHostLabel(bucketArn#accountId, false)
                70 => EndpointFunctions.IsValidHostLabel(bucketArn!.AccountId, false),
                // accessPointName_ssa_2 = bucketArn#resourceId[3]
                71 => (accessPointNameSsa2 = EndpointFunctions.Index(bucketArn!.ResourceId, 3))
                    is not null,
                // isValidHostLabel(accessPointName_ssa_1, false)
                72 => EndpointFunctions.IsValidHostLabel(accessPointNameSsa1!, false),
                // stringEquals(outpostType, "accesspoint")
                73 => outpostType! == ("accesspoint"),
                // isValidHostLabel(accessPointName_ssa_2, false)
                74 => EndpointFunctions.IsValidHostLabel(accessPointNameSsa2!, false),
                _ => throw new UnreachableException(),
            };

